<?php
/**
 * ApiKey: read-only value object representing one row from `api_keys`.
 *
 * Holds the metadata of an external REST API key for the /v1/* consensus
 * API. The plaintext key material is NEVER stored here: only the
 * SHA-256 hex digest (`keyHash`) and the readable `rv_XXXXXXXX` prefix
 * (`prefix`) are persisted. The plaintext is generated by
 * App\Api\ApiKeyService::generateKey() and shown to the operator
 * exactly once.
 *
 * Scopes:
 *   - SCOPE_FULL: every /v1/* capability (create runs, read results,
 *     cancel, usage, webhooks).
 *   - SCOPE_READ: read-only access (status/events/result/models/usage).
 *     Attempts to create or cancel runs are rejected with 403.
 *
 * @project  RevoAp
 * @author   Mikhail Deynekin <mikhail@deynekin.com>
 * @site     https://Deynekin.com
 * @email    mikhail@deynekin.com
 * @version  1.0.0
 * @since    2026-09-19
 */
declare(strict_types=1);

namespace App\Api;

final readonly class ApiKey
{
    public const SCOPE_FULL = 'full';
    public const SCOPE_READ = 'read';

    /** @var list<string> Well-known scope list. */
    public const SCOPES = [self::SCOPE_FULL, self::SCOPE_READ];

    /**
     * @param list<string> $scopes Active scopes of this key.
     */
    public function __construct(
        public int     $id,
        public string  $label,
        public string  $keyHash,
        public string  $prefix,
        public array   $scopes,
        public int     $rpmLimit,
        public int     $dailyLimit,
        public ?string $expiresAt = null,
        public ?string $lastUsedAt = null,
        public ?string $revokedAt = null,
        public ?string $createdAt = null,
    ) {}

    /** True when the key has full capabilities. */
    public function hasFullScope(): bool
    {
        return in_array(self::SCOPE_FULL, $this->scopes, true);
    }

    /** True when the key has read capabilities (full scope implies read). */
    public function hasReadScope(): bool
    {
        return $this->hasFullScope() || in_array(self::SCOPE_READ, $this->scopes, true);
    }

    /** True when the key is not revoked and its TTL (if any) is in the future. */
    public function isUsable(?int $nowTs = null): bool
    {
        if ($this->revokedAt !== null) {
            return false;
        }
        if ($this->expiresAt !== null) {
            $now = $nowTs ?? time();
            $expiry = strtotime($this->expiresAt);
            if ($expiry === false || $expiry <= $now) {
                return false;
            }
        }
        return true;
    }

    /**
     * Operator-facing representation. Always omits the key hash so a
     * dump of a UI payload cannot leak anything usable.
     *
     * @return array<string,mixed>
     */
    public function toPublicArray(): array
    {
        return [
            'id'           => $this->id,
            'label'        => $this->label,
            'prefix'       => $this->prefix,
            'scopes'       => $this->scopes,
            'rpm_limit'    => $this->rpmLimit,
            'daily_limit'  => $this->dailyLimit,
            'expires_at'   => $this->expiresAt,
            'last_used_at' => $this->lastUsedAt,
            'revoked_at'   => $this->revokedAt,
            'created_at'   => $this->createdAt,
        ];
    }

    /**
     * Hydrate from a database row (snake_case keys) or an in-memory
     * mirror. Unknown scopes are dropped silently; a key whose scope
     * list is empty after filtering gets the read-only default so a
     * malformed row cannot accidentally escalate to full access.
     *
     * @param array<string,mixed> $row
     */
    public static function fromRow(array $row): self
    {
        $scopes = [];
        $raw    = $row['scopes'] ?? self::SCOPE_FULL;
        if (is_string($raw)) {
            $parts = array_map('trim', explode(',', $raw));
            $parts = array_values(array_unique(array_filter(
                $parts,
                static fn(string $s): bool => in_array($s, self::SCOPES, true)
            )));
            // A malformed scope list must degrade to LEAST privilege
            // (read-only), never to full access.
            $scopes = $parts === [] ? [self::SCOPE_READ] : $parts;
        } elseif (is_array($raw)) {
            foreach ($raw as $s) {
                if (in_array((string)$s, self::SCOPES, true)) {
                    $scopes[] = (string)$s;
                }
            }
            $scopes = array_values(array_unique($scopes));
            if ($scopes === []) {
                $scopes = [self::SCOPE_READ];
            }
        }
        return new self(
            id:         isset($row['id']) ? (int)$row['id'] : 0,
            label:      (string)($row['label'] ?? ''),
            keyHash:    strtolower((string)($row['key_hash'] ?? '')),
            prefix:     strtolower((string)($row['prefix'] ?? '')),
            scopes:     $scopes,
            rpmLimit:   isset($row['rpm_limit']) ? (int)$row['rpm_limit'] : 30,
            dailyLimit: isset($row['daily_limit']) ? (int)$row['daily_limit'] : 1000,
            expiresAt:  self::nullableString($row['expires_at'] ?? null),
            lastUsedAt: self::nullableString($row['last_used_at'] ?? null),
            revokedAt:  self::nullableString($row['revoked_at'] ?? null),
            createdAt:  self::nullableString($row['created_at'] ?? null),
        );
    }

    private static function nullableString(mixed $v): ?string
    {
        if ($v === null) {
            return null;
        }
        $s = trim((string)$v);
        return $s === '' ? null : $s;
    }
}
